def classify(label, heights):
    print(f"{label}: {heights}")
    n = len(heights)
    for i in range(1, n - 1):
        left = heights[i - 1]
        here = heights[i]
        right = heights[i + 1]
        if here > left and here > right:
            print(f"  km {i}: {here} > {left} and {here} > {right}, a local max")
        elif here < left and here < right:
            print(f"  km {i}: {here} < {left} and {here} < {right}, a local min")
    top = 0
    bottom = 0
    for i in range(n):
        if heights[i] > heights[top]:
            top = i
        if heights[i] < heights[bottom]:
            bottom = i
    print(f"  absolute max {heights[top]} at km {top}, absolute min {heights[bottom]} at km {bottom}")

classify("the trail of Example 10", [120, 180, 150, 210, 170, 260])
classify("always climbing", [10, 20, 30, 40])
classify("one point", [75])
classify("a tie for the top", [5, 9, 2, 9, 4])

