from fractions import Fraction

def f(x):
    return x**3 - 3 * x**2 + 1

def closed_interval(a, b):
    print(f"on [{a}, {b}]:")
    candidates = [a]
    for c in [0, 2]:
        if a < c < b:
            candidates.append(c)
            print(f"  critical number {c} is inside, f({c}) = {f(c)}")
        else:
            print(f"  critical number {c} is not inside, skip it")
    candidates.append(b)
    print(f"  endpoints: f({a}) = {f(a)}, f({b}) = {f(b)}")
    top = f(a)
    bottom = f(a)
    for x in candidates:
        if f(x) > top:
            top = f(x)
        if f(x) < bottom:
            bottom = f(x)
    at_top = []
    at_bottom = []
    for x in candidates:
        if f(x) == top:
            at_top.append(x)
        if f(x) == bottom:
            at_bottom.append(x)
    print(f"  max {top} at x = {at_top}, min {bottom} at x = {at_bottom}")

closed_interval(Fraction(-1, 2), 4)
closed_interval(1, 4)
closed_interval(3, 5)
closed_interval(-1, 3)
closed_interval(0, 3)

